// Package axis implements a single virtual servo axis.
//
// The axis is a purely simulated kinematic model: it does not command any real
// hardware. Position and velocity advance with a fixed sample period under
// bounded speed |v| <= MaxSpeed and bounded acceleration |a| <= MaxAccel.
//
// Motion is generated by re-planning a time-optimal trapezoidal velocity
// profile from the CURRENT measured position and velocity every time a target
// is set (including while already moving), so a new goal never restarts from
// an old point or produces a position/velocity jump.
package axis

import (
	"errors"
	"math"
)

// Mode describes what the axis is currently trying to do.
type Mode int

const (
	Idle Mode = iota
	Moving
	SoftStopping
	EmergencyStopping
)

// Config holds the fixed kinematic limits and sample period of an axis.
type Config struct {
	MaxSpeed float64
	MaxAccel float64
	Step     float64 // seconds per Step() call
}

func (c Config) Validate() error {
	switch {
	case !(c.MaxSpeed > 0):
		return errors.New("axis: MaxSpeed must be positive")
	case !(c.MaxAccel > 0):
		return errors.New("axis: MaxAccel must be positive")
	case !(c.Step > 0):
		return errors.New("axis: Step must be positive")
	}
	return nil
}

// Axis is a virtual position-controlled axis.
type Axis struct {
	maxSpeed float64
	maxAccel float64
	dt       float64

	pos float64
	vel float64

	mode     Mode
	target   float64
	hasGoal  bool
	estopped bool
}

func New(cfg Config) (*Axis, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	return &Axis{maxSpeed: cfg.MaxSpeed, maxAccel: cfg.MaxAccel, dt: cfg.Step}, nil
}

func (a *Axis) Position() float64       { return a.pos }
func (a *Axis) Velocity() float64       { return a.vel }
func (a *Axis) Mode() Mode              { return a.mode }
func (a *Axis) Target() (float64, bool) { return a.target, a.hasGoal }
func (a *Axis) EmergencyStopped() bool  { return a.estopped }

// AtTarget reports rest exactly on the commanded goal.
func (a *Axis) AtTarget() bool {
	return a.mode == Moving && a.hasGoal &&
		math.Abs(a.vel) <= settleVelTol(a.maxAccel, a.dt) &&
		math.Abs(a.pos-a.target) <= settlePosTol(a.maxAccel, a.dt)
}

// Numerical arrival tolerances. They are many orders of magnitude below one
// sample of travel and only absorb floating-point round-off of the final
// analytic settle, never a physically meaningful remaining motion.
func settleVelTol(amag, dt float64) float64 { return amag * dt * 1e-6 }
func settlePosTol(amag, dt float64) float64 { return amag * dt * dt * 1e-3 }

// SettleIfAtTarget snaps residual round-off away once the axis is inside the
// in-position window at rest. It is called when the executing motion is being
// marked complete so the observed state is exactly (target, 0).
func (a *Axis) SettleIfAtTarget() {
	if a.AtTarget() {
		a.pos = a.target
		a.vel = 0
	}
}

// SetTarget commands a new goal, planning from the current real state.
func (a *Axis) SetTarget(p float64) error {
	if a.estopped {
		return errors.New("axis: emergency stop is active; call Reset first")
	}
	a.target = p
	a.hasGoal = true
	a.mode = Moving
	return nil
}

// ClearTarget drops the goal without forcing a stop.
func (a *Axis) ClearTarget() {
	a.hasGoal = false
	if a.mode == Moving {
		a.mode = Idle
	}
}

// SoftStop commands a controlled maximum-deceleration stop to the current
// natural stopping point; new motion can be commanded afterwards.
func (a *Axis) SoftStop() {
	if a.estopped {
		return
	}
	a.hasGoal = false
	if a.vel == 0 {
		a.mode = Idle
		return
	}
	a.mode = SoftStopping
}

// EmergencyStop brakes at the limit and latches a fault until Reset.
func (a *Axis) EmergencyStop() {
	a.hasGoal = false
	a.estopped = true
	a.mode = EmergencyStopping
}

// Reset clears a latched emergency stop once at rest.
func (a *Axis) Reset() error {
	if a.mode == EmergencyStopping && a.vel != 0 {
		return errors.New("axis: cannot reset while emergency braking")
	}
	a.estopped = false
	if a.mode == EmergencyStopping {
		a.mode = Idle
	}
	return nil
}

// Step advances the simulation by one fixed sample period.
func (a *Axis) Step() {
	switch a.mode {
	case Idle:
	case SoftStopping, EmergencyStopping:
		a.brakeToRest()
		if a.vel == 0 && a.mode == SoftStopping {
			a.mode = Idle
		}
	case Moving:
		a.stepTowardTarget()
	}
}

// brakeToRest integrates max-deceleration braking, settling exactly at the
// natural stop point with zero velocity (partial final step).
func (a *Axis) brakeToRest() {
	amag, dt := a.maxAccel, a.dt
	speed := math.Abs(a.vel)
	if speed == 0 {
		return
	}
	sign := math.Copysign(1, a.vel)
	if speed <= amag*dt+1e-12 {
		// Stop within this sample: integrate to the stop instant.
		t := speed / amag
		a.pos += 0.5 * a.vel * t
		a.vel = 0
		return
	}
	old := a.vel
	a.vel -= sign * amag * dt
	a.pos += 0.5 * (old + a.vel) * dt
}

// stepTowardTarget moves one sample toward the goal using a predictive,
// time-optimal controller. All arithmetic is in the along-axis scalar u, the
// velocity component toward the goal (negative while moving away).
//
// Each sample evaluates the three admissible acceleration commands (+MaxAccel,
// -MaxAccel, coast) at their PREDICTED end-of-sample state and keeps the one
// that (1) does not cross the goal and (2) stays inside the braking envelope
// sqrt(2*MaxAccel*dist). This look-ahead removes the one-sample lag that makes a
// reactive bang-bang controller overshoot a point target and oscillate.
//
// The last fraction of a sample is settled analytically (braking exactly to rest
// on the goal; a symmetric pulse for targets shorter than one sample), which keeps
// |v| <= MaxSpeed and |a| <= MaxAccel at every sample and lands exactly on the
// target. Because the controller reads the CURRENT (pos, vel) every step, a new
// goal is always continued from the real state with no jump.
func (a *Axis) stepTowardTarget() {
	dx := a.target - a.pos
	if dx == 0 {
		a.vel = 0
		return
	}
	amag, dt, vmax := a.maxAccel, a.dt, a.maxSpeed
	// Absorb final round-off once inside the in-position window so callers
	// observe an exact rest state on the goal.
	if math.Abs(a.vel) <= settleVelTol(amag, dt) &&
		math.Abs(dx) <= settlePosTol(amag, dt) {
		a.pos = a.target
		a.vel = 0
		return
	}
	s := math.Copysign(1, dx)
	dist := math.Abs(dx)
	u := a.vel * s

	// One-sample rest-to-rest reach: from u (>=0 toward the goal), a symmetric
	// accelerate-then-brake pulse within dt can cover at most
	// u*dt + 0.5*a*(dt/2)^2 ... handled generally below. When even the max
	// admissible step cannot make progress without crossing, and the goal is
	// reachable inside one sample, land exactly on it. This covers targets so
	// close that ordinary bang-bang steps cannot represent the motion.
	if dist <= amag*dt*dt && math.Abs(u) <= settleVelTol(amag, dt) {
		a.pos = a.target
		a.vel = 0
		return
	}

	// Predictive one-step choice. Evaluate the three admissible commands
	// (+MaxAccel, -MaxAccel, coast) over this sample and keep the one whose
	// end state stays inside the braking envelope sqrt(2*a*dNext) and does not
	// cross the goal. Choosing against the PREDICTED end state removes the one
	// sample lag that otherwise makes a reactive bang-bang controller cross a
	// point target and oscillate.
	best := math.Inf(1)
	var bestNu, bestStep float64
	for _, acc := range [3]float64{amag, -amag, 0} {
		nu := clampVel(u+acc*dt, vmax)
		step := 0.5 * (u + nu) * dt
		dNext := dist - step
		score := math.Abs(dNext) * 1e3
		if dNext < 0 {
			score += 1e12 // do not cross the goal
		} else {
			// Prefer staying at or below the braking envelope at the end of
			// the sample; penalize excess speed squared so aggressive braking
			// is chosen early instead of coasting into an overshoot.
			env := math.Sqrt(2 * amag * dNext)
			if nu > env {
				excess := nu - env
				score += excess * excess * 1e6
			}
		}
		if score < best {
			best, bestNu, bestStep = score, nu, step
		}
	}

	// Analytic final sample: if maximum braking over this sample would reach
	// the goal and the speed is small enough to stop within one sample, land
	// exactly on the goal at rest. Deceleration j = u^2/(2*dist) is verified to
	// stay within MaxAccel, so the last |dv| <= MaxAccel*Step. This is
	// evaluated against the full braking step, independent of the scored choice.
	if u > 0 && u <= amag*dt+1e-12 {
		brakeStep := u*dt - 0.5*amag*dt*dt
		if brakeStep+1e-12 >= dist {
			j := u * u / (2 * dist)
			if j <= amag+1e-9 {
				a.pos = a.target
				a.vel = 0
				return
			}
		}
	}
	// Recovery from a tiny discrete overshoot: once the axis is on the far side
	// and slow enough to stop within one sample, settle directly onto the goal. The
	// correction is a fraction of one sample of travel and |dv| <= MaxAccel*Step.
	if u < 0 && -u <= amag*dt && dist <= vmax*dt {
		a.pos = a.target
		a.vel = 0
		return
	}

	a.vel = s * bestNu
	a.pos += s * bestStep
}

func clampVel(v, limit float64) float64 {
	if v > limit {
		return limit
	}
	if v < -limit {
		return -limit
	}
	return v
}

// Snapshot captures the full dynamic state, including mid-motion states.
type Snapshot struct {
	Pos           float64 `json:"pos"`
	Vel           float64 `json:"vel"`
	Mode          Mode    `json:"mode"`
	Target        float64 `json:"target"`
	HasGoal       bool    `json:"has_goal"`
	EmergencyStop bool    `json:"emergency_stop"`
}

func (a *Axis) Snapshot() Snapshot {
	return Snapshot{
		Pos: a.pos, Vel: a.vel, Mode: a.mode,
		Target: a.target, HasGoal: a.hasGoal, EmergencyStop: a.estopped,
	}
}

// Restore overwrites state from a snapshot; in-progress motion is preserved
// (nothing is assumed to have reached the target).
func (a *Axis) Restore(s Snapshot) {
	a.pos, a.vel, a.mode = s.Pos, s.Vel, s.Mode
	a.target, a.hasGoal, a.estopped = s.Target, s.HasGoal, s.EmergencyStop
}
